typedef unsigned int nslSoundId;
typedef int SSEventId;

class entity;

enum EventType
{
    SS_UNDERWATER_FRONT = 80,
    SS_UNDERWATER_REAR = 95
};

class SoundScriptManager
{
public:
    static SoundScriptManager *inst();
    nslSoundId getSoundId(SSEventId e);
    void endEvent(SSEventId e, float fadeOutTime = 0);
    SSEventId startEvent(EventType etype, entity *e = 0, float fadeInTime = 0);
};

extern int nslGetSoundStatus(nslSoundId sound);
extern void nslDampenGuardSound(nslSoundId sound);
extern void nslSetSoundEmitter(unsigned int emitter, nslSoundId sound);
extern void nslDampenAllSounds(float dampenLevel);
extern void nslUndampenAllSounds();

enum
{
    NSL_SOUNDSTATUS_INVALID = 0
};

class WaveSound
{
    char padding0[0x138];
    nslSoundId underwaterSnd1;
    nslSoundId underwaterSnd2;
    char padding1[0x2D0];
    SSEventId underwaterEventFront;
    SSEventId underwaterEventRear;
    char padding2[0x78];
    bool underwater;
    char padding3[0x1B];

public:
    unsigned int behindTheCamera;
    void wentUnderWater(bool under);
};

void WaveSound::wentUnderWater( bool under )
{
//  int i=0;
  underwater = under;
  if ( under )
  {
    // The underwater rumble
		underwaterEventFront = SoundScriptManager::inst()->startEvent(SS_UNDERWATER_FRONT, 0);
		underwaterSnd1	      = SoundScriptManager::inst()->getSoundId(underwaterEventFront);

		underwaterEventFront = SoundScriptManager::inst()->startEvent(SS_UNDERWATER_REAR, 0);
		underwaterSnd2	      = SoundScriptManager::inst()->getSoundId(underwaterEventFront);

		if (nslGetSoundStatus( underwaterSnd1 ) != NSL_SOUNDSTATUS_INVALID)
			nslDampenGuardSound(underwaterSnd1);

		if (nslGetSoundStatus( underwaterSnd2 ) != NSL_SOUNDSTATUS_INVALID)
		{
			nslSetSoundEmitter(behindTheCamera, underwaterSnd2);
			nslDampenGuardSound(underwaterSnd2);
		}

    nslDampenAllSounds(.2f);
  }
  else
  {
		SoundScriptManager::inst()->endEvent(SS_UNDERWATER_FRONT);
		SoundScriptManager::inst()->endEvent(SS_UNDERWATER_REAR);
    nslUndampenAllSounds();
    //underWaterModifier  = 0.1f;
  }
}
